import{_ as i,b as s,e,a8 as t}from"./chunks/framework.CD0vREyi.js";const n="data:image/png;base64,",p="data:image/png;base64,",m=JSON.parse('{"title":"Line patterns","description":"","frontmatter":{"date":1787610772000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"guide/line-patterns.md","filePath":"guide/line-patterns.md","lastUpdated":1787610772000,"timestamp":1787610772000,"datetime":"2026-08-24T22:32:52.000Z","contributors":[{"commits":1,"email":"anders@melander.dk","name":"Anders Melander","avatar":"https://gravatar.com/avatar/a6bff52a3ccbe999ab6406528ffe48f1","maintainer":false,"links":[]}]}'),l={name:"guide/line-patterns.md"};function r(o,a,h,d,c,k){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="line-patterns" tabindex="-1">Line patterns <a class="header-anchor" href="#line-patterns" aria-label="Permalink to &quot;Line patterns&quot;">​</a></h1><p>Graphics32 defines several functions to support non-uniform lines. This includes gradient lines, dashed lines etc.</p><p>The concept is pretty simple: Each <a href="/api/GR32/TBitmap32">TBitmap32</a> object contains a dynamic array of colors, and a color index which ‘crawls’ along the array. The line drawing algorithm samples colors from the color array, at the current color position. The color index is automatically incremented after each sample.</p><p>The color index, accessed through the <a href="/api/GR32/TBitmap32/TCustomBitmap32/Properties/StippleCounter">StippleCounter</a> property, wraps itself automatically at the edges of the color array. It can move in both directions depending on the value of the <a href="/api/GR32/TBitmap32/TCustomBitmap32/Properties/StippleStep">StippleStep</a> property, which in turn can be positive or negative. Its value may even be fractional in which case the resulting color is interpolated between two colors of the color array.</p><p>The <a href="/api/GR32/TBitmap32/TCustomBitmap32/Methods/AdvanceStippleCounter">AdvanceStippleCounter</a> method advances <code>StippleCounter</code> by the value of <code>StippleStep</code>.</p><p>The <a href="/api/GR32/TBitmap32/TCustomBitmap32/Methods/GetStippleColor">GetStippleColor</a> function returns the color at the current color index position and then, by default, advances the color index position by calling <code>AdvanceStippleCounter</code> so that the next <code>GetStippleColor</code> call will return a color value from the next position.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>The stippled line drawing functions internally calls <code>GetStippleColor</code> and <code>AdvanceStippleCounter</code> for each pixel, so you do not need to do that manually.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>GetStippleColor</code> and <code>AdvanceStippleCounter</code> is not thread safe and the <code>StippleCounter</code> value is shared by all threads accessing the bitmap. If you are drawing stippled lines, or manually calling <code>GetStippleColor</code> or <code>AdvanceStippleCounter</code>, on the same bitmap from multiple threads, then you need to synchronize the calls so only one thread is inside these functions at a time.</p></div><div class="info custom-block"><p class="custom-block-title">Note</p><p>Drawing functions that support line patterns have <strong>P</strong> in their <a href="./naming-conventions/">postfix</a> (for example, <code>LineFSP</code>).</p></div><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><h4 id="drawing-a-dashed-line" tabindex="-1">Drawing a dashed line <a class="header-anchor" href="#drawing-a-dashed-line" aria-label="Permalink to &quot;Drawing a dashed line&quot;">​</a></h4><p>The following code snippet draws a dashed line made up of alternating white dashes and red dots.</p><div class="language-pascal vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">pascal</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Set up the stipple pattern</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Bitmap.SetStipple([clWhite32, clWhite32, clWhite32, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, clRed32, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Bitmap.StippleStep := </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 1 pixel per color in pattern</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Draw a stippled line</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Bitmap.LineFSP(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><div class="center custom-block"><p><img src="`+n+`" alt="Dashed line"></p></div><h4 id="drawing-a-gradient-line" tabindex="-1">Drawing a gradient line <a class="header-anchor" href="#drawing-a-gradient-line" aria-label="Permalink to &quot;Drawing a gradient line&quot;">​</a></h4><p>The following code snippet draws a gradient line. The gradient transitions smoothly from red to blue to yellow.</p><div class="language-pascal vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">pascal</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Set up the gradient pattern</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Bitmap.SetStipple([clRed32, clBlue32, clYellow32]);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Bitmap.StippleStep := </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Smooth transition</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Draw a gradient line</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Bitmap.LineFSP(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><div class="center custom-block"><p><img src="`+p+'" alt="Gradient line"></p></div>',18)])])}const u=i(l,[["render",r]]);export{m as __pageData,u as default};
